326	func TestParseErrors(t *testing.T) {
327		without := func(line string) string {
328			if !strings.Contains(synthValid, line) {
329				t.Fatalf("test bug: %q not in the synthetic file", line)
330			}
331			return strings.Replace(synthValid, line, "", 1)
332		}
333		replace := func(old, new string) string {
334			if !strings.Contains(synthValid, old) {
335				t.Fatalf("test bug: %q not in the synthetic file", old)
336			}
337			return strings.Replace(synthValid, old, new, 1)
338		}
339	
340		tests := []struct {
341			name string
342			file string // default "bad--admin.http"
343			data string
344			rule string // lower-case word the error must name, besides the file name
345		}{
346			{name: "missing scenario header", data: without("# scenario: synthetic scenario\n"), rule: "scenario"},
347			{name: "missing nexus header", data: without("# nexus: 3.98.1-01 COMMUNITY (synthetic)\n"), rule: "nexus"},
348			{name: "missing measured header", data: without("# measured: 2026-11-17\n"), rule: "measured"},
349			{name: "missing account header", data: without("# account: synthetic account\n"), rule: "account"},
350			{name: "missing redacted header", data: without("# redacted: synthetic redaction\n"), rule: "redacted"},
351			{name: "nexus value empty", data: replace("# nexus: 3.98.1-01 COMMUNITY (synthetic)", "# nexus:"), rule: "nexus"},
352			{name: "nexus version unreadable", data: replace("3.98.1-01 COMMUNITY", "banana COMMUNITY"), rule: "nexus"},
353			{name: "nexus edition missing", data: replace("3.98.1-01 COMMUNITY (synthetic)", "3.98.1-01"), rule: "nexus"},
354			{name: "measured is not a date", data: replace("# measured: 2026-11-17", "# measured: yesterday"), rule: "measured"},
355			{name: "record value unknown", data: replace("# redacted: synthetic redaction\n", "# redacted: synthetic redaction\n# record: maybe\n"), rule: "record"},
356			{name: "unknown identity suffix", file: "bad--root.http", data: synthValid, rule: "identity"},
357			{name: "no identity suffix", file: "bad.http", data: synthValid, rule: "identity"},
358			{name: "not an http file", file: "bad--admin.txt", data: synthValid, rule: ".http"},
359			{name: "empty file", data: "", rule: "scenario"},
360			{name: "no blank line between the headers and the request", data: strings.Replace(synthValid, "\nGET ", "GET ", 1), rule: "blank line"},
361			{name: "no blank line between the request and the response", data: strings.Replace(synthValid, "\nHTTP/1.1 200", "HTTP/1.1 200", 1), rule: "blank line"},
362			{name: "request line without a version", data: replace("GET /v2/_catalog HTTP/1.1", "GET /v2/_catalog"), rule: "request"},
363			{name: "request without Host", data: without("Host: 127.0.0.1:30482\n"), rule: "host"},
364			{name: "status line with a non numeric code", data: replace("HTTP/1.1 200 OK", "HTTP/1.1 abc OK"), rule: "status"},
365			{name: "status line that is not a status line", data: replace("HTTP/1.1 200 OK", "200 OK"), rule: "status"},
366			{name: "pending with a response", data: replace("# redacted: synthetic redaction\n", "# redacted: synthetic redaction\n# record: pending\n"), rule: "pending"},
367			{name: "response missing without pending", data: synthHeaders + synthRequest, rule: "response"},
368		}
369		for _, tt := range tests {
370			t.Run(tt.name, func(t *testing.T) {
371				file := tt.file
372				if file == "" {
373					file = "bad--admin.http"
374				}
375				f, err := nexusfixture.Parse("synthetic", file, []byte(tt.data))
376				if err == nil {
377					t.Fatalf("Parse accepted the file: %+v", f)
378				}
379				msg := strings.ToLower(err.Error())
380				if !strings.Contains(msg, strings.ToLower(file)) {
381					t.Errorf("error %q does not name the file %q", err, file)
382				}
383				if !strings.Contains(msg, tt.rule) {
384					t.Errorf("error %q does not name the rule %q", err, tt.rule)
385				}
386			})
387		}
