419	// Import integrity: a verbatim body that Nexus sent with a Content-Length has
420	// exactly that many bytes (a stub only summarises its body, so it is skipped).
421	func TestVerbatimBodiesMatchTheirContentLength(t *testing.T) {
422		fixtures, err := nexusfixture.Load("catalog")
423		if err != nil {
424			t.Fatalf("Load(catalog): %v", err)
425		}
426		checked := 0
427		for _, f := range fixtures {
428			for i, ex := range f.Exchanges {
429				cl := ex.Header.Get("Content-Length")
430				if ex.Stub != "" || cl == "" {
431					continue
432				}
433				n, err := strconv.Atoi(cl)
434				if err != nil {
435					t.Errorf("%s exchange %d: Content-Length %q is not a number", f.Name, i, cl)
436					continue
437				}
438				if n != len(ex.Body) {
439					t.Errorf("%s exchange %d: Content-Length %d but the body has %d bytes", f.Name, i, n, len(ex.Body))
440				}
441				checked++
442			}
443		}
444		if checked == 0 {
445			t.Error("no verbatim body with a Content-Length was checked: the test checks nothing")
446		}
447	}
