449	// Rule of the plan: the format package is imported by the recorder, a dev tool
450	// of the nexus-bench binary, so it must not drag in "testing". Only the
451	// fakenexus sub-package may.
452	func TestProductionCodeDoesNotImportTesting(t *testing.T) {
453		files, err := filepath.Glob("*.go")
454		if err != nil {
455			t.Fatal(err)
456		}
457		prod := 0
